var dataList=new Array;function BuildScreen(){var template=$("#Template_Tile").html(),html="";for(i=0;i<dataList.length;i++){var id=dataList[i].Label.replace(/ /g,"");html+=template.replace(/\$ID\$/g,id).replace(/\$TITLE\$/g,dataList[i].Label).replace(/\$VALUE1\$/g,dataList[i].V1.toLocaleString()).replace(/\$VALUE2\$/g,dataList[i].V2.toLocaleString()).replace(/\$TOTAL\$/g,(dataList[i].V1+dataList[i].V2).toLocaleString())}$("body").append(html),AnimateBars()}function AnimateBars(){for(i=0;i<dataList.length;i++){var total=dataList[i].V1+dataList[i].V2,width1=dataList[i].V1/total*100,width2=dataList[i].V2/total*100;dataList[i].V1>dataList[i].V2?(width1=100,width2=dataList[i].V2/dataList[i].V1*100):(width2=100,width1=dataList[i].V1/dataList[i].V2*100);var id=dataList[i].Label.replace(/ /g,"");$("#Value1_"+id).css({width:width1+"%"}),$("#Value2_"+id).css({width:width2+"%"}),window.setTimeout(AddGradient,4e3)}$(".valueouter span").each((function(){AnimateNumbers(this)})),$(".total span").each((function(){AnimateNumbers(this)}))}function AddGradient(){$(".leftouter").addClass("gradientcolor"),$(".rightouter").addClass("gradientcolor")}function AnimateNumbers(el){$({Counter:0}).animate({Counter:$(el).text().replace(",","")},{duration:4100,easing:"swing",step:function(){$(el).text(Math.ceil(this.Counter).toLocaleString())}})}function data(label,v1,v2){this.Label=label,this.V1=v1,this.V2=v2}$((function(){dataList.push(new data("Total",27259,27010)),dataList.push(new data("Most in a day 20260718",833,858)),dataList.push(new data("Daily Average",247,245)),BuildScreen()}));